const STARTER = [
  ['Sketch','UG_CREATE_SKETCH','S'],['Extrude','UG_MODELING_EXTRUDED_FEATURE','D'],['Edge Blend','UG_MODELING_BLEND_FEATURE','F'],
  ['Hole','UG_MODELING_HOLE_FEATURE','A'],['Revolve','UG_MODELING_REVOLVED_FEATURE','E'],['Chamfer','UG_MODELING_CHAMFER_FEATURE','Q'],
  ['Project Curve','UG_CURVE_PROJECT','R'],['Combined Projection','UG_CURVE_COMBINE','C'],['Measure','UG_INFO_GEOMETRIC_MEASUREMENT','V'],
  ['Fit View','UG_VIEW_FIT','W'],['Unite','UG_MODELING_UNITE_FEATURE','X'],['Subtract','UG_MODELING_SUBTRACT_FEATURE','Z'],
  ['Pattern Feature','UG_MODELING_PATTERNFEATURE_FEATURE','G'],['Mirror Feature','UG_MODELING_MIRRORFEATURE_FEATURE','T'],
  ['Top View','UG_VIEW_POPUP_ORIENT_TOP','Shift+W'],['Left View','UG_VIEW_POPUP_ORIENT_LEFT','Shift+A'],
  ['Front View','UG_VIEW_POPUP_ORIENT_FRONT','Shift+S'],['Right View','UG_VIEW_POPUP_ORIENT_RIGHT','Shift+D'],
  ['Isometric View','UG_VIEW_POPUP_ORIENT_TFRISO','Shift+Q']
].map(([label,id,key])=>({label,id,key}));
const CATALOG = [
  ...STARTER.map(({label,id})=>({label,id})),
  {label:'Shell',id:'UG_MODELING_SHELL_FEATURE'}, {label:'Draft',id:'UG_MODELING_DRAFT_FEATURE'},
  {label:'Datum Plane',id:'UG_MODELING_DATUM_PLANE'}, {label:'Offset Curve',id:'UG_CURVE_OFFSET'},
  {label:'Bottom View',id:'UG_VIEW_POPUP_ORIENT_BOTTOM'}, {label:'Back View',id:'UG_VIEW_POPUP_ORIENT_BACK'},
  {label:'Trimetric View',id:'UG_VIEW_POPUP_ORIENT_TFRTRI'}
];
const ROWS = [
  [['Escape','Esc'],['Digit1','1'],['Digit2','2'],['Digit3','3'],['Digit4','4'],['Digit5','5'],['Digit6','6'],['Digit7','7'],['Digit8','8'],['Digit9','9'],['Digit0','0'],['Backspace','Backspace','wide']],
  [['Tab','Tab','wide'],...('QWERTYUIOP'.split('').map(x=>['Key'+x,x])),['BracketLeft','['],['BracketRight',']']],
  [['CapsLock','Caps','wide'],...('ASDFGHJKL'.split('').map(x=>['Key'+x,x])),['Semicolon',';'],['Quote',"'"],['Enter','Enter','wide']],
  [['ShiftLeft','Shift','wide'],...('ZXCVBNM'.split('').map(x=>['Key'+x,x])),['Comma',','],['Period','.'],['Slash','/'],['ShiftRight','Shift','wide']],
  [['ControlLeft','Ctrl','wide'],['AltLeft','Alt','wide'],['Space','Space','space'],['AltRight','Alt','wide'],['ControlRight','Ctrl','wide']]
];
const $ = id=>document.getElementById(id);
const safeLoad=()=>{try{const value=JSON.parse(localStorage.getItem('nx-shortcuts-v1'));return valid(value)?value:structuredClone(STARTER)}catch{return structuredClone(STARTER)}};
let bindings=safeLoad(), recording=-1, sketchRecording=-1, down=new Set(), lastKey='';
let keyboardMode=localStorage.getItem('nx-keyboard-mode')==='sketch'?'sketch':'modeling';
let libraryMode=localStorage.getItem('nx-library-mode')==='sketch'?'sketch':'modeling';
const MOUSE_LABELS=['Middle button','Right button','Mouse 4','Mouse 5','Wheel up','Wheel down'];
const RADIAL_NAMES=['Right-click hold','Ctrl + right-click hold','Shift + right-click hold'];
const DIRECTIONS=['North','North-east','East','South-east','South','South-west','West','North-west'];
const SKETCH_STARTER=[['Line','UG_SKETCH_LINE_BY_TWO_POINTS','L'],['Circle','UG_SKETCH_CIRCLE_FROM_CENTER','O'],['Rectangle','UG_SKETCH_RECTANGLE_BY_TWO_POINTS','R'],['Quick Trim','UG_SKETCH_QUICK_TRIM','T'],['Rapid Dimension','UG_SKETCH_RAPID_DIMENSION','D'],['Finish Sketch','UG_SKETCH_FINISH','F']].map(([label,id,key])=>({label,id,key}));
let mouseMappings=JSON.parse(localStorage.getItem('nx-mouse-v1')||'null')||MOUSE_LABELS.map(label=>({label,command:null}));
let radialMenus=JSON.parse(localStorage.getItem('nx-radials-v1')||'null')||RADIAL_NAMES.map(name=>({name,slots:Array(8).fill(null)}));
let sketchBindings=JSON.parse(localStorage.getItem('nx-sketch-v1')||'null')||structuredClone(SKETCH_STARTER);
let pickerTarget={type:'keyboard'};
function valid(value){return Array.isArray(value)&&value.length<=200&&value.every(x=>x&&typeof x.label==='string'&&typeof x.id==='string'&&typeof x.key==='string'&&/^[A-Za-z0-9_.:-]{1,128}$/.test(x.id)&&x.label.length<100&&x.key.length<60)&&new Set(value.filter(x=>x.key).map(x=>x.key.toUpperCase())).size===value.filter(x=>x.key).length}
function save(){localStorage.setItem('nx-shortcuts-v1',JSON.stringify(bindings));localStorage.setItem('nx-mouse-v1',JSON.stringify(mouseMappings));localStorage.setItem('nx-radials-v1',JSON.stringify(radialMenus));localStorage.setItem('nx-sketch-v1',JSON.stringify(sketchBindings));render();renderLibrary();renderMouse();renderRadials();renderSketch()}
function combo(event){const mods=[];if(event.ctrlKey)mods.push('Ctrl');if(event.altKey)mods.push('Alt');if(event.shiftKey)mods.push('Shift');if(event.metaKey)mods.push('Meta');let key=event.key.length===1?event.key.toUpperCase():event.key;const special={Escape:'Esc',' ':'Space',Control:'Ctrl',Alt:'Alt',Shift:'Shift',Meta:'Meta',ArrowUp:'Up',ArrowDown:'Down',ArrowLeft:'Left',ArrowRight:'Right'};key=special[key]||key;if(['Ctrl','Alt','Shift','Meta'].includes(key))return mods.join('+');return [...mods,key].join('+')}
function activeMods(){return ['ControlLeft','ControlRight'].some(x=>down.has(x))?'Ctrl':null}
function previewKey(letter){const mods=[];if(activeMods())mods.push('Ctrl');if(['AltLeft','AltRight'].some(x=>down.has(x)))mods.push('Alt');if(['ShiftLeft','ShiftRight'].some(x=>down.has(x)))mods.push('Shift');return [...mods,letter].join('+')}
function activeBindings(){return keyboardMode==='sketch'?sketchBindings:bindings}
function renderKeyboard(){const box=$('keyboard');const list=activeBindings();box.replaceChildren();for(const row of ROWS){const line=document.createElement('div');line.className='key-row';for(const [code,label,width] of row){const key=document.createElement('button');key.type='button';key.className='key'+(width?' '+width:'');key.dataset.code=code;key.setAttribute('aria-label',label);const lookup=previewKey(label);const match=list.find(x=>x.key===lookup);if(match)key.classList.add('assigned');if(down.has(code))key.classList.add('pressed');const name=document.createElement('span');name.className='letter';name.textContent=label;const command=document.createElement('span');command.className='key-command';command.textContent=match?.label||'';key.append(name,command);if(match){key.draggable=true;key.title='Drag '+match.label+' to another key';key.addEventListener('dragstart',e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/x-nx-shortcut',keyboardMode+'|'+lookup);key.classList.add('dragging')});key.addEventListener('dragend',()=>key.classList.remove('dragging'))}key.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';key.classList.add('drop-target')});key.addEventListener('dragleave',()=>key.classList.remove('drop-target'));key.addEventListener('drop',e=>{e.preventDefault();key.classList.remove('drop-target');const payload=e.dataTransfer.getData('text/x-nx-shortcut').split('|');if(payload[0]===keyboardMode)moveOrSwapShortcut(payload[1],previewKey(label),list)});key.addEventListener('click',()=>{const chosen=previewKey(label);if(keyboardMode==='sketch'&&sketchRecording>=0)assignSketch(sketchRecording,chosen);else if(keyboardMode==='modeling'&&recording>=0)assign(recording,chosen);else showMatch(lookup)});line.append(key)}box.append(line)}}
function moveOrSwapShortcut(sourceKey,targetKey,list){if(!sourceKey||!targetKey||sourceKey===targetKey)return;const source=list.findIndex(x=>x.key.toUpperCase()===sourceKey.toUpperCase());if(source<0)return;const target=list.findIndex(x=>x.key.toUpperCase()===targetKey.toUpperCase());list[source].key=targetKey;if(target>=0)list[target].key=sourceKey;save();showMatch(targetKey);toast(target>=0?'Swapped '+list[source].label+' and '+list[target].label:'Moved '+list[source].label+' to '+targetKey)}
function renderBindings(){const box=$('bindings');box.replaceChildren();bindings.forEach((item,index)=>{const row=document.createElement('div');row.className='binding';const name=document.createElement('div');name.innerHTML='<div class="binding-name"></div><div class="binding-id"></div>';name.children[0].textContent=item.label;name.children[1].textContent=item.id;const key=document.createElement('button');key.type='button';key.className='shortcut'+(recording===index?' recording':'');key.textContent=recording===index?'Press keys…':item.key||'Set shortcut';key.addEventListener('click',()=>{recording=index;render();key.focus()});const remove=document.createElement('button');remove.type='button';remove.className='remove';remove.textContent='×';remove.setAttribute('aria-label','Remove '+item.label);remove.addEventListener('click',()=>{bindings.splice(index,1);recording=-1;save()});row.append(name,key,remove);box.append(row)})}
function openPicker(target,title){pickerTarget=target;$('pickerTitle').textContent=title;$('commandSearch').value='';renderResults();$('commandDialog').showModal();$('commandSearch').focus()}
function renderMouse(){const box=$('mouseMappings');box.replaceChildren();mouseMappings.forEach((item,index)=>{const button=document.createElement('button');button.className='mouse-map';button.innerHTML='<strong></strong><small></small>';button.children[0].textContent=item.label;button.children[1].textContent=item.command?item.command.label+' · '+item.command.id:'Click to assign';button.onclick=()=>openPicker({type:'mouse',index},'Assign '+item.label);box.append(button)})}
function renderRadials(){const box=$('radialMenus');box.replaceChildren();radialMenus.forEach((menu,menuIndex)=>{const card=document.createElement('div');card.className='radial-card';const title=document.createElement('h3');title.textContent=menu.name;const wheel=document.createElement('div');wheel.className='radial-wheel';menu.slots.forEach((command,slot)=>{const button=document.createElement('button');button.className='radial-slot';const direction=document.createElement('span');direction.textContent=DIRECTIONS[slot];button.append(direction,document.createTextNode(command?.label||'Assign'));button.onclick=()=>openPicker({type:'radial',menu:menuIndex,slot},'Assign '+menu.name+' · '+DIRECTIONS[slot]);wheel.append(button)});const center=document.createElement('div');center.className='radial-center';center.textContent='RADIAL';wheel.append(center);card.append(title,wheel);box.append(card)})}
function renderSketch(){const box=$('sketchBindings');box.replaceChildren();sketchBindings.forEach((item,index)=>{const row=document.createElement('div');row.className='binding';const name=document.createElement('div');name.innerHTML='<div class="binding-name"></div><div class="binding-id"></div>';name.children[0].textContent=item.label;name.children[1].textContent=item.id;const key=document.createElement('button');key.className='shortcut'+(sketchRecording===index?' recording':'');key.textContent=sketchRecording===index?'Press keys…':item.key||'Set shortcut';key.onclick=()=>{sketchRecording=index;recording=-1;renderSketch();key.focus()};const remove=document.createElement('button');remove.className='remove';remove.textContent='×';remove.onclick=()=>{sketchBindings.splice(index,1);save()};row.append(name,key,remove);box.append(row)});$('sketchCount').textContent=sketchBindings.length+' sketch commands'}
const basicRenderBindings=renderBindings,basicRenderSketch=renderSketch;
function decorateJournals(box,list){list.forEach((item,index)=>window.NX_JOURNAL_COMMANDS?.decorate(box.children[index].children[0],item,list,()=>{save();toast('Journal name and command ID saved; shortcut preserved')},()=>{recording=-1;sketchRecording=-1}))}
renderBindings=()=>{basicRenderBindings();decorateJournals($('bindings'),bindings)};
renderSketch=()=>{basicRenderSketch();decorateJournals($('sketchBindings'),sketchBindings)};
function render(){renderKeyboard();renderBindings();$('count').textContent=bindings.length+' commands assigned'}
function showMatch(key){lastKey=key;$('liveKeys').textContent=key||'Press any key';const match=activeBindings().find(x=>x.key.toUpperCase()===key.toUpperCase());$('liveCommand').textContent=match?.label||'No command assigned';$('liveCommand').style.color=match?'#fff':'#aaa9c4'}
let pendingSwap=null;
function assign(index,key){if(!key||['Ctrl','Alt','Shift','Meta'].includes(key))return;const clash=bindings.findIndex((x,i)=>i!==index&&x.key.toUpperCase()===key.toUpperCase());if(clash>=0){pendingSwap={index,clash,key};recording=-1;render();$('swapMessage').textContent=key+' is assigned to '+bindings[clash].label+'. Swap its shortcut with '+bindings[index].label+'?';$('swapDialog').showModal();return}bindings[index].key=key;recording=-1;save();showMatch(key);toast('Assigned '+key+' to '+bindings[index].label)}
function assignSketch(index,key){if(!key||['Ctrl','Alt','Shift','Meta'].includes(key))return;const clash=sketchBindings.findIndex((x,i)=>i!==index&&x.key.toUpperCase()===key.toUpperCase());if(clash>=0){pendingSwap={scope:'sketch',index,clash,key};sketchRecording=-1;renderSketch();$('swapMessage').textContent=key+' is assigned to '+sketchBindings[clash].label+' in Sketching. Swap it with '+sketchBindings[index].label+'?';$('swapDialog').showModal();return}sketchBindings[index].key=key;sketchRecording=-1;save();toast('Assigned '+key+' to '+sketchBindings[index].label+' in Sketching')}
$('cancelSwap').onclick=()=>{$('swapDialog').close();pendingSwap=null};
$('confirmSwap').onclick=()=>{if(!pendingSwap)return;const {scope,index,clash,key}=pendingSwap;const list=scope==='sketch'?sketchBindings:bindings;const previous=list[index].key;list[index].key=key;list[clash].key=previous;pendingSwap=null;$('swapDialog').close();save();if(scope!=='sketch')showMatch(key);toast('Swapped shortcuts')};
$('swapDialog').addEventListener('close',()=>{pendingSwap=null});
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3200)}
document.addEventListener('keydown',e=>{down.add(e.code);renderKeyboard();if(sketchRecording>=0){e.preventDefault();if(e.key==='Escape'){sketchRecording=-1;renderSketch();return}if(e.key==='Backspace'||e.key==='Delete'){sketchBindings[sketchRecording].key='';sketchRecording=-1;save();return}if(['Control','Alt','Shift','Meta'].includes(e.key))return;assignSketch(sketchRecording,combo(e));return}if(recording>=0){e.preventDefault();if(e.key==='Escape'){recording=-1;render();return}if(e.key==='Backspace'||e.key==='Delete'){bindings[recording].key='';recording=-1;save();return}if(['Control','Alt','Shift','Meta'].includes(e.key))return;assign(recording,combo(e));return}if(e.target.matches('input,select,textarea'))return;showMatch(combo(e))});
document.addEventListener('keyup',e=>{down.delete(e.code);renderKeyboard()});window.addEventListener('blur',()=>{down.clear();renderKeyboard()});
$('resetBtn').onclick=()=>{if(confirm('Reset all assignments to the starter layout?')){bindings=structuredClone(STARTER);save();toast('Starter layout restored')}};
let installedCommands=window.NX_COMMANDS||[];
if(!installedCommands.length){$('libraryCount').textContent='Library unavailable';toast('NX command library could not load')}else{const groups=[...new Set(installedCommands.map(x=>x.group))].sort();for(const group of groups){const option=document.createElement('option');option.value=group;option.textContent=group;$('categoryFilter').append(option)}renderResults();renderLibrary()}
function addCommand(item){if(pickerTarget.type==='mouse'){mouseMappings[pickerTarget.index].command={label:item.label,id:item.id};save();if($('commandDialog').open)$('commandDialog').close();toast('Added '+item.label);return}if(pickerTarget.type==='radial'){radialMenus[pickerTarget.menu].slots[pickerTarget.slot]={label:item.label,id:item.id};save();if($('commandDialog').open)$('commandDialog').close();toast('Added '+item.label);return}const sketch=pickerTarget.type==='sketch';const list=sketch?sketchBindings:bindings;if(list.some(x=>x.id===item.id)){toast('That command is already assigned');return}list.push({label:item.label,id:item.id,key:''});if($('commandDialog').open)$('commandDialog').close();setKeyboardMode(sketch?'sketch':'modeling');if(sketch)sketchRecording=list.length-1;else recording=list.length-1;save();setTimeout(()=>document.querySelector('.keyboard-panel').scrollIntoView({behavior:'smooth',block:'start'}),0);toast('Press a key or combination for '+item.label)}
function renderLibrary(){const query=$('librarySearch').value.trim().toLowerCase();const category=$('categoryFilter').value;const list=$('libraryResults');const destination=libraryMode==='sketch'?sketchBindings:bindings;list.replaceChildren();if(!installedCommands.length)return;const available=installedCommands.filter(x=>libraryMode!=='sketch'||x.id.startsWith('UG_SKETCH'));const matches=available.filter(x=>(!category||x.group===category)&&(!query||x.label.toLowerCase().includes(query)||x.id.toLowerCase().includes(query))).sort((a,b)=>a.group.localeCompare(b.group)||a.label.localeCompare(b.label));$('libraryCount').textContent=matches.length.toLocaleString()+' of '+available.length.toLocaleString()+' '+(libraryMode==='sketch'?'sketching':'modeling')+' codes';for(const item of matches.slice(0,100)){const assigned=destination.some(x=>x.id===item.id);const button=document.createElement('button');button.type='button';button.className='library-item';const text=document.createElement('span');const label=document.createElement('strong');label.textContent=item.label;const code=document.createElement('small');code.textContent=item.group+' · '+item.id;text.append(label,code);const badge=document.createElement('em');badge.textContent=assigned?'Assigned':'+ Add';button.append(text,badge);button.onclick=()=>{if(assigned){const index=destination.findIndex(x=>x.id===item.id);$(libraryMode==='sketch'?'sketchBindings':'bindings').children[index]?.scrollIntoView({behavior:'smooth',block:'center'});return}pickerTarget={type:libraryMode==='sketch'?'sketch':'keyboard'};addCommand(item)};list.append(button)}if(!matches.length){const empty=document.createElement('div');empty.className='library-empty';empty.textContent='No matching NX command code';list.append(empty)}}
function setLibraryMode(mode){libraryMode=mode;localStorage.setItem('nx-library-mode',mode);$('libraryModeToggle').checked=mode==='sketch';$('libraryDestination').textContent=mode==='sketch'?'Adding to Sketching keyboard':'Adding to Modeling keyboard';document.querySelector('.library-panel').classList.toggle('sketch-destination',mode==='sketch');if(mode==='sketch')$('categoryFilter').value='Sketching';else if($('categoryFilter').value==='Sketching')$('categoryFilter').value='';renderLibrary()}
$('librarySearch').addEventListener('input',renderLibrary);$('categoryFilter').addEventListener('change',renderLibrary);$('libraryModeToggle').addEventListener('change',e=>setLibraryMode(e.target.checked?'sketch':'modeling'));
function renderResults(){const query=$('commandSearch').value.trim().toLowerCase();const list=$('commandResults');list.replaceChildren();const seen=new Set();const candidates=[...CATALOG,...installedCommands].filter(x=>{if(seen.has(x.id))return false;seen.add(x.id);if(pickerTarget.type==='keyboard')return !bindings.some(b=>b.id===x.id);if(pickerTarget.type==='sketch')return x.id.startsWith('UG_SKETCH')&&!sketchBindings.some(b=>b.id===x.id);return true}).filter(x=>!query||x.label.toLowerCase().includes(query)||x.id.toLowerCase().includes(query)).sort((a,b)=>(a.group||'').localeCompare(b.group||'')||a.label.localeCompare(b.label)).slice(0,80);for(const item of candidates){const button=document.createElement('button');button.type='button';button.className='command-result';const label=document.createElement('span');label.textContent=item.label;const code=document.createElement('small');code.textContent=(item.group?item.group+' · ':'')+item.id;button.append(label,code);button.onclick=()=>addCommand(item);list.append(button)}if(!candidates.length){const empty=document.createElement('div');empty.className='command-empty';empty.textContent='No matching installed command';list.append(empty)}}
$('addBtn').onclick=()=>openPicker({type:'keyboard'},'Add modeling command');
$('addSketchBtn').onclick=()=>openPicker({type:'sketch'},'Add sketching command');
$('closeDialog').onclick=()=>$('commandDialog').close();$('commandSearch').oninput=renderResults;
$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());const next=data.bindings??data;if(!valid(next))throw Error('Invalid layout');bindings=next;if(Array.isArray(data.sketchBindings))sketchBindings=data.sketchBindings;if(Array.isArray(data.mouseMappings))mouseMappings=data.mouseMappings;if(Array.isArray(data.radialMenus))radialMenus=data.radialMenus;if(data.roleVisibility)window.NX_ROLE_VISIBILITY?.importState(data.roleVisibility);save();toast('Layout imported')}catch(err){toast('Could not import layout: '+err.message)}e.target.value=''};
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
$('exportJsonBtn').onclick=()=>download('NX-shortcut-layout.json',JSON.stringify({format:'nx-shortcut-studio-v3',version:'2606',bindings,sketchBindings,mouseMappings,radialMenus,roleVisibility:window.NX_ROLE_VISIBILITY?.getState()},null,2),'application/json');
function writeAccelerators(xml,container,items){container.replaceChildren();for(const item of items.filter(x=>x.key)){if(item.id==='NX_SHORTCUT_STUDIO_TOGGLE_REFERENCE_GEOMETRY')throw Error('Edit the journal command ID: the old placeholder is not registered in NX.');const action=xml.createElement('Action');const metadata=installedCommands.find(x=>x.id===item.id);action.setAttribute('name',item.id);action.setAttribute('type',metadata?.type||item.type||'button');const accelerators=xml.createElement('Accelerators');const accel=xml.createElement('Accel');accel.setAttribute('name',item.key);accelerators.append(accel);action.append(accelerators);container.append(action)}}
$('exportMtxBtn').onclick=async()=>{try{const roleText=window.NX_BASE_ROLE;if(!roleText)throw Error('Base role unavailable');const xml=new DOMParser().parseFromString(roleText,'application/xml');if(xml.querySelector('parsererror'))throw Error('Base role invalid');const root=xml.documentElement;root.setAttribute('name','NX_SHORTCUT_STUDIO_'+Date.now());root.setAttribute('title','NX Shortcut Studio - Modeling and Sketching');root.querySelector('Description').textContent='Modeling shortcuts are stored in the role repository. Sketching shortcuts are application-only in UG_APP_SKETCH_TASK. Ribbon and Resource Bar tab visibility is customized per workspace.';const generalActions=root.querySelector('Repository > Content > Actions');if(!generalActions)throw Error('Base role lacks actions repository');const sketchProfile=[...root.querySelectorAll('Profile')].find(x=>x.getAttribute('name')==='UG_APP_SKETCH_TASK');if(!sketchProfile)throw Error('Base role lacks the Sketch task profile');let sketchContent=[...sketchProfile.children].find(x=>x.tagName==='Content');if(!sketchContent){sketchContent=xml.createElement('Content');sketchContent.setAttribute('mode','edit');sketchProfile.prepend(sketchContent)}let sketchActions=[...sketchContent.children].find(x=>x.tagName==='Actions');if(!sketchActions){sketchActions=xml.createElement('Actions');sketchContent.append(sketchActions)}writeAccelerators(xml,generalActions,bindings);writeAccelerators(xml,sketchActions,sketchBindings);window.NX_ROLE_VISIBILITY?.applyToXml(xml);const text='<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(root);download('NX Shortcut Studio - 2606.mtx',text,'application/xml');toast('Shortcuts and tab visibility exported to the NX role')}catch(err){toast('MTX export failed: '+err.message)}};

document.addEventListener('nx:add-journal-command',event=>{const {id,label='Toggle Create Reference Geometry',scope='sketch'}=event.detail||{};if(!window.NX_JOURNAL_COMMANDS.validateId(id))return;const list=scope==='sketch'?sketchBindings:bindings;let index=list.findIndex(item=>item.id===id);if(index<0)index=list.findIndex(item=>item.id==='NX_SHORTCUT_STUDIO_TOGGLE_REFERENCE_GEOMETRY'&&label==='Toggle Create Reference Geometry');if(index>=0){window.NX_JOURNAL_COMMANDS.configure(list[index],list,label,id);save();toast('Journal command updated; existing shortcut preserved');return}list.push({label,id,key:'',kind:'journal',type:'button'});setKeyboardMode(scope==='sketch'?'sketch':'modeling');if(scope==='sketch')sketchRecording=list.length-1;else recording=list.length-1;save();document.querySelector('.keyboard-panel').scrollIntoView({behavior:'smooth',block:'start'});toast('Press a key for '+label)});
function setKeyboardMode(mode){keyboardMode=mode;localStorage.setItem('nx-keyboard-mode',mode);$('modeToggle').checked=mode==='sketch';$('modeBanner').textContent=mode==='sketch'?'Sketching shortcuts':'Modeling shortcuts';document.querySelector('.keyboard-panel').classList.toggle('sketch-mode',mode==='sketch');recording=-1;sketchRecording=-1;renderKeyboard();showMatch(lastKey)}
$('modeToggle').addEventListener('change',e=>setKeyboardMode(e.target.checked?'sketch':'modeling'));
render();renderMouse();renderRadials();renderSketch();setKeyboardMode(keyboardMode);setLibraryMode(libraryMode);
if(document.modelContext?.registerTool){
  try{void Promise.resolve(document.modelContext.registerTool({name:'set_nx_shortcut',title:'Set NX shortcut',description:'Assign a keyboard combination to a command already listed in the NX shortcut editor.',inputSchema:{type:'object',properties:{commandId:{type:'string'},shortcut:{type:'string'}},required:['commandId','shortcut'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const index=bindings.findIndex(x=>x.id===input.commandId);if(index<0)throw Error('Command is not in the layout');if(typeof input.shortcut!=='string'||!/^(?:(?:Ctrl|Alt|Shift|Meta)\+)*[A-Za-z0-9]+$/.test(input.shortcut))throw Error('Invalid shortcut');const conflict=bindings.findIndex((x,i)=>i!==index&&x.key.toUpperCase()===input.shortcut.toUpperCase());if(conflict>=0)throw Error('Shortcut already assigned');bindings[index].key=input.shortcut;save();return{commandId:input.commandId,shortcut:input.shortcut}}})).catch(()=>{});}catch{}
}
